arguments.command:
cd /testbed && python -c "
from sympy.combinatorics import DihedralGroup, PermutationGroup, Permutation
from sympy.combinatorics.named_groups import SymmetricGroup, AlternatingGroup

# Test sylow_subgroup with various groups
print('Testing sylow_subgroup:')

# Test various Dihedral groups
for n in [3, 4, 5, 6, 7, 8, 9, 10, 12, 18, 20, 25, 50]:
    G = DihedralGroup(n)
    for p in [2, 3, 5]:
        if G.order() % p == 0:
            try:
                S = G.sylow_subgroup(p=p)
                print(f'DihedralGroup({n}).sylow_subgroup(p={p}): order {S.order()}')
            except Exception as e:
                print(f'DihedralGroup({n}).sylow_subgroup(p={p}) ERROR: {e}')

# Test with Symmetric and Alternating groups
for name, G in [('SymmetricGroup(4)', SymmetricGroup(4)), 
                ('SymmetricGroup(5)', SymmetricGroup(5)),
                ('AlternatingGroup(4)', AlternatingGroup(4)),
                ('AlternatingGroup(5)', AlternatingGroup(5))]:
    for p in [2, 3]:
        if G.order() % p == 0:
            try:
                S = G.sylow_subgroup(p=p)
                print(f'{name}.sylow_subgroup(p={p}): order {S.order()}')
            except Exception as e:
                print(f'{name}.sylow_subgroup(p={p}) ERROR: {e}')

print('All tests passed!')
"

